      var id = btn.getAttribute('data-hub-id');
      var isActive = id === activeHubId;
      btn.classList.toggle('active', isActive);
      var kind = btn.dataset.iconKind || 'home';
      var iconWrap = btn.querySelector('.browsing-hub-item__icon');
