      var testing = detailItemProbeTesting || !!(raw && (raw.status === 'running' || raw.status === 'testing'));
      if (statusEl) {
        statusEl.textContent = networkStatusText(testing ? raw : cache);
        statusEl.classList.toggle('detail-network-status--error', !!(raw && raw.status === 'error'));
        statusEl.classList.toggle('detail-network-status--testing', testing);
      }
      updateQualityRowLabel();
      var showRec = cache && cache.status === 'done' && cache.recommendedLabel && getDetailQuality() === 'auto';
      if (recRow) recRow.hidden = !showRec;
      if (recEl && showRec) {
        recEl.innerHTML = '<strong>Suggested for this connection:</strong> ' + escapeHtml(cache.recommendedLabel);
      }
