      homeBlock.className = 'design-review-composed design-review-home';
      homeBlock.innerHTML = '<p class="design-review-label">Home visual language</p>' + '<div class="home-pivots" data-cols="4">' + '<button class="nav-item home-pivot active" tabindex="0">All</button>' + '<button class="nav-item home-pivot" tabindex="0">TV</button>' + '<button class="nav-item home-pivot" tabindex="0">Films</button>' + '<button class="nav-item home-pivot home-pivot-search" tabindex="0">Search</button>' + '</div>';
