    screen.innerHTML = '<div class="profile-picker-main" id="profile-picker-main">' + '<div class="profile-picker-header" id="profile-header">' + '<h1 class="screen-title screen-title-compact profile-picker-title">Select User</h1>' + '</div>' + '<p class="status-msg profile-picker-status" id="profile-status" hidden></p>' + '<div class="profile-picker-body" id="profile-body">' + '<div class="profile-picker-row" id="profile-row" data-focus-zone="profile-picker-profiles"></div>' + '<div class="profile-picker-pin" id="profile-pin" hidden>' + '<p class="pin-display" id="pin-display"></p>' + '<p class="pin-error" id="pin-error" hidden></p>' + '<div class="pin-pad" id="pin-pad"></div>' + '</div></div></div>';
    root.appendChild(screen);
